#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAXN 1005

char S[MAXN];
char cur[MAXN + 5];

// Incrementa o número representado como string em cur
int increment(char *num, int len) {
    int carry = 1;
    for (int i = len - 1; i >= 0; i--) {
        int sum = (num[i] - '0') + carry;
        if (sum >= 10) {
            num[i] = '0';
            carry = 1;
        } else {
            num[i] = sum + '0';
            carry = 0;
            break;
        }
    }
    if (carry) {
        // Desloca tudo para a direita para inserir '1' na posição 0
        for (int i = len; i >= 1; i--) {
            num[i] = num[i - 1];
        }
        num[0] = '1';
        len++;
        num[len] = '\0';
    }
    return len;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    for (int i = 0; i < n; i++) {
        int d;
        scanf("%d", &d);
        S[i] = (char)(d + '0');
    }
    S[n] = '\0';

    for (int L = 1; L <= n; L++) {
        // Copia o prefixo de tamanho L como o candidato A
        for (int i = 0; i < L; i++) {
            cur[i] = S[i];
        }
        cur[L] = '\0';
        int cur_len = L;

        int idx = L;
        bool ok = true;

        while (idx < n) {
            cur_len = increment(cur, cur_len);
            for (int j = 0; j < cur_len; j++) {
                if (idx + j >= n) {
                    if (j > 0) {
                        ok = false;
                    }
                    idx += j;
                    break;
                }
                if (S[idx + j] != cur[j]) {
                    ok = false;
                    break;
                }
            }
            if (!ok) break;
            idx += cur_len;
        }

        if (ok && idx == n) {
            // Encontrou o menor A (pois testamos em ordem crescente de comprimento)
            for (int i = 0; i < L; i++) {
                putchar(S[i]);
            }
            putchar('\n');
            return 0;
        }
    }

    return 0;
}
